mapper.select:
SELECT FROM ql_registration r INNER JOIN ql_customer c ON c.id = r.customer_id INNER JOIN ql_session s ON s.id = r.session_id LEFT JOIN ql_registration_batch b ON b.id = r.batch_id LEFT JOIN ql_customer buyer ON buyer.id = b.submitted_by_customer_id LEFT JOIN ql_customer ref ON ref.id = r.session_referrer_customer_id
AND (c.nickname LIKE CONCAT('%', #{bo.nickname}, '%') OR c.real_name LIKE CONCAT('%', #{bo.nickname}, '%') OR CONVERT(c.customer_no USING utf8mb4) LIKE CONCAT('%', #{bo.nickname}, '%'))
AND s.session_number = #{bo.sessionNumber}
AND r.registration_status = #{bo.registrationStatus}
AND COALESCE(b.payment_status, r.payment_status) = #{bo.paymentStatus}
ORDER BY r.registered_at DESC

mapper.update:
UPDATE ql_registration
SET payment_status = #{toStatus}, revision = revision + 1,
    updated_by = #{operatorId}, updated_at = #{updatedAt}
WHERE id = #{id} AND payment_status = #{fromStatus}

UPDATE ql_registration_batch
SET payment_status = #{toStatus}
WHERE id = #{batchId} AND payment_status = #{fromStatus}

UPDATE ql_registration
SET payment_status = #{toStatus}, revision = revision + 1,
    updated_by = #{operatorId}, updated_at = #{updatedAt}
WHERE batch_id = #{batchId}
